function locals() {
  return { xs: [1, 2], yes: true, n: true };
}

function sameAs(want, err, out) {
  if (want && want.error) {
    expect(err).to.be.an(Error);
    expect(err.message).to.contain(want.error);
    return;
  }
  if (err) {
    throw err;
  }
  expect(out).to.equal(want);
}

function attempt(fn) {
  try {
    return [null, fn()];
  } catch (e) {
    return [e];
  }
}

describe('nested blocks and {% parent %} (native)', function () {
  shapes.forEach(function (s) {
    var mem = swigModule.loaders.memory(s.files, '/');

    it(s.id + ' sync: ' + s.title, function () {
      var r = attempt(function () {
        return new swigModule.Swig({ loader: mem, cache: false }).renderFile('/t.html', locals());
      });
      sameAs(s.sync, r[0], r[1]);
    });

    it(s.id + ' sync, parents cached: ' + s.title, function () {
      var engine = new swigModule.Swig({ loader: mem });
      Object.keys(s.files).forEach(function (name) {
        if (name !== '/t.html') {
          attempt(function () { engine.compileFile(name); });
        }
      });
      var r = attempt(function () { return engine.renderFile('/t.html', locals()); });
      sameAs(s.sync, r[0], r[1]);
    });

    it(s.id + ' async: ' + s.title, function (done) {
      var loader = { async: true, resolve: mem.resolve, load: function (id, cb) {
        setImmediate(function () {
          var src;
          try { src = mem.load(id); } catch (e) { cb(e); return; }
          cb(null, src);
        });
      } };
      new swigModule.Swig({ loader: loader, cache: false }).renderFile('/t.html', locals(), function (err, out) {
        try {
          sameAs(s.async, err, out);
        } catch (e) {
          done(e);
          return;
        }
        done();
      });
    });
  });
});
